mapper.update:
    	UPDATE
   			REP_REVEAL
		SET STATUS = 'D'
		,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
		,UPDATE_TIME = current date
		WHERE
			REP_ID = #{repId,jdbcType=VARCHAR}
		AND PRODID = #{portnum,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(START_DATE,'yyyy-mm-dd'),TO_CHAR(START_DATE,'yyyy-mm-dd'),'0') = #{startDate,jdbcType=VARCHAR}
		AND nvl2(TO_CHAR(END_DATE,'yyyy-mm-dd'),TO_CHAR(END_DATE,'yyyy-mm-dd'),'0') = #{endDate,jdbcType=VARCHAR}
		AND STATUS='E'
